    .hero-actions,
    .deal-actions,
    .section-heading {
      display: flex;
      flex-wrap: wrap;
      gap: 1rem;
      align-items: center;
    }

    .hero-actions {
      margin-top: 2rem;
    }

    .button {
      display: inline-flex;
      align-items: center;
      justify-content: center;
      gap: 0.45rem;
      min-height: 48px;
      padding: 0.85rem 1.2rem;
      color: #171008;
      background: var(--accent-strong);
      border: 1px solid var(--accent-strong);
      border-radius: 999px;
      box-shadow: 0 16px 40px #00000066;
      cursor: pointer;
      font-weight: 800;
      text-decoration: none;
    }

    .button:hover {
      color: #171008;
      background: #ffe38f;
      border-color: #ffe38f;
    }

    .button.secondary {
      color: var(--text);
      background: var(--surface-strong);
      border-color: var(--border);
    }

    .button.secondary:hover {
      color: var(--text);
      background: var(--surface-soft);
      border-color: var(--accent);
    }

    .hero-card {
      position: relative;
      min-height: 540px;
      padding: clamp(1rem, 3vw, 1.5rem);
      background:
        linear-gradient(150deg, #ffffff14, transparent 36%),
        linear-gradient(180deg, #191d27, #0d0f16);
      border: 1px solid var(--border);
      border-radius: var(--radius-lg);
      box-shadow: 0 34px 80px #00000099;
      overflow: hidden;
    }

    .hero-card::before {
      content: "";
      position: absolute;
      inset: 11% 8% auto auto;
      width: 16rem;
      height: 16rem;
      background: radial-gradient(circle, #f1c86a99, transparent 70%);
      filter: blur(10px);
    }

    .product-stage {
      position: absolute;
      inset: auto 8% 9%;
      display: grid;
      gap: 1rem;
    }

    .showcase-bag {
      position: relative;
      width: min(100%, 23rem);
      min-height: 23rem;
      margin-inline: auto;
      border: 1px solid #ffffff22;
      border-radius: 42% 42% 28% 28%;
      background:
        radial-gradient(circle at 35% 26%, #fff4c2, transparent 16%),
        linear-gradient(145deg, #d8a74e, #5e3d16 64%, #15100a);
      box-shadow:
        inset -34px -42px 68px #00000080,
        0 35px 72px #000000b3;
    }

    .showcase-bag::before {
      content: "";
      position: absolute;
      left: 50%;
      top: -2.3rem;
      width: 9rem;
      height: 7rem;
      border: 1.1rem solid #dec06f;
      border-bottom: 0;
      border-radius: 999px 999px 0 0;
      transform: translateX(-50%);
    }

    .showcase-bag::after {
      content: "NOVA";
      position: absolute;
      inset: 50% auto auto 50%;
      color: #ffe9a4;
      font-size: clamp(2.4rem, 7vw, 4.8rem);
      font-weight: 900;
      letter-spacing: 0.14em;
      transform: translate(-50%, -50%);
    }

    .floating-note {
      display: grid;
      grid-template-columns: auto 1fr;
      gap: 0.75rem;
      align-items: center;
      width: min(100%, 24rem);
      padding: 1rem;
      background: #0c0e14f2;
      border: 1px solid var(--border);
      border-radius: var(--radius-md);
    }

    .floating-note strong {
      display: block;
      color: var(--text);
    }

    .floating-note p {
      margin: 0.1rem 0 0;
      font-size: 0.95rem;
    }

    .spark {
      display: grid;
      width: 46px;
      height: 46px;
      place-items: center;
      color: #171008;
      background: var(--accent-strong);
      border-radius: 16px;
      font-weight: 900;
    }

    .section {
      padding-block: clamp(2.75rem, 7vw, 5.8rem);
    }

    .section-heading {
      justify-content: space-between;
      margin-bottom: 1.5rem;
    }

    .section-heading p {
      max-width: 34rem;
      margin: 0;
    }

    .category-controls {
      display: flex;
      flex-wrap: wrap;
      gap: 0.65rem;
      margin-bottom: 1.25rem;
    }

    .filter-button {
      padding: 0.65rem 0.95rem;
      color: var(--muted);
      background: var(--surface);
      border: 1px solid var(--border);
      border-radius: 999px;
      cursor: pointer;
    }

    .filter-button:hover,
    .filter-button[aria-pressed="true"] {
      color: #171008;
      background: var(--accent-strong);
      border-color: var(--accent-strong);
    }

    .product-grid,
    .editorial-grid {
      display: grid;
      grid-template-columns: repeat(3, minmax(0, 1fr));
      gap: 1rem;
    }

    .product-card,
    .article-card,
    .deal-panel,
    .newsletter {
      background: linear-gradient(180deg, #171a24, #0f1118);
      border: 1px solid var(--border);
      border-radius: var(--radius-md);
      box-shadow: 0 22px 50px #00000059;
      overflow: hidden;
    }

    .product-card {
      display: grid;
      min-width: 0;
    }

    .product-media {
      display: grid;
      min-height: 245px;
      place-items: center;
      background:
        radial-gradient(circle at 50% 45%, #ffffff20 0 5rem, transparent 8rem),
        linear-gradient(135deg, #252a39, #11131a);
    }

    .product-shape {
      display: grid;
      width: 11rem;
      height: 11rem;
      place-items: center;
      color: #141008;
      background: var(--product-gradient);
      border: 1px solid #ffffff2e;
      border-radius: var(--shape);
      box-shadow:
        inset -20px -24px 44px #00000057,
        0 24px 50px #00000080;
      font-size: 3rem;
    }

    .product-body,
    .article-body {
      display: grid;
      gap: 0.85rem;
      padding: 1.1rem;
    }

    .product-meta {
      display: flex;
      justify-content: space-between;
      gap: 0.75rem;
      color: var(--muted);
      font-size: 0.95rem;
    }

    .price {
      color: var(--text);
      font-weight: 900;
    }

    .rating {
      color: var(--accent-strong);
      font-weight: 800;
    }

    .deal-panel {
      position: relative;
      display: grid;
      grid-template-columns: minmax(0, 1fr) minmax(250px, 0.75fr);
      gap: 1.5rem;
      align-items: center;
      padding: clamp(1.25rem, 4vw, 2.4rem);
      background:
        linear-gradient(120deg, #221704, transparent 45%),
        linear-gradient(135deg, #171a24, #0a0c11);
    }

    .deal-badge {
      display: inline-flex;
      width: fit-content;
      padding: 0.5rem 0.8rem;
      color: #171008;
      background: var(--accent-strong);
      border-radius: 999px;
      font-weight: 900;
    }

    .deal-copy p {
      max-width: 44rem;
    }

    .countdown {
      display: grid;
      grid-template-columns: repeat(3, minmax(0, 1fr));
      gap: 0.75rem;
    }

    .time-box {
      display: grid;
      min-height: 108px;
      place-items: center;
      padding: 1rem;
      text-align: center;
      background: #08090d;
      border: 1px solid var(--border);
      border-radius: var(--radius-sm);
    }

    .time-box strong {
      display: block;
      color: var(--accent-strong);
      font-size: clamp(1.8rem, 5vw, 3rem);
      line-height: 1;
    }

    .time-box span {
      color: var(--muted);
      font-weight: 700;
    }

    .article-card {
      display: grid;
      min-width: 0;
    }

    .article-media {
      min-height: 230px;
      background:
        linear-gradient(135deg, var(--article-a), transparent),
        radial-gradient(circle at 80% 20%, var(--article-b), transparent 13rem),
        #11131a;
    }

    .article-tag {
      width: fit-content;
      padding: 0.35rem 0.7rem;
      color: var(--accent-strong);
      background: #d8a74e1c;
      border: 1px solid #d8a74e66;
      border-radius: 999px;
      font-size: 0.82rem;
      font-weight: 900;
      letter-spacing: 0.08em;
      text-transform: uppercase;
    }

    .article-card a {
      font-weight: 800;
    }

    .newsletter {
      display: grid;
      grid-template-columns: minmax(0, 0.85fr) minmax(280px, 1fr);
      gap: 1rem;
      align-items: center;
      padding: clamp(1.25rem, 4vw, 2rem);
    }

    .newsletter-form {
      display: grid;
      gap: 0.8rem;
    }

    .form-row {
      display: flex;
      gap: 0.75rem;
    }

    label {
      color: var(--text);
      font-weight: 800;
    }

    input[type="email"] {
      width: 100%;
      min-height: 52px;
      padding: 0.9rem 1rem;
      color: var(--text);
      background: #08090d;
      border: 1px solid var(--border);
      border-radius: 999px;
    }

    input[type="email"][aria-invalid="true"] {
      border-color: var(--danger);
      box-shadow: 0 0 0 3px #ffb4a833;
    }

    .form-help,
    .form-error,
    .form-success {
      margin: 0;
      font-size: 0.95rem;
    }

    .form-error {
      color: var(--danger);
    }

    .form-success {
      color: var(--success);
    }

    .site-footer {
      padding-block: 2rem;
      color: var(--muted);
      border-top: 1px solid var(--border);
      background: #050507;
    }

    .footer-inner {
      display: flex;
      flex-wrap: wrap;
      gap: 1rem;
      align-items: center;
      justify-content: space-between;
    }

    .footer-inner ul {
      display: flex;
      flex-wrap: wrap;
      gap: 0.9rem;
      margin: 0;
      padding: 0;
      list-style: none;
    }

    .toast {
      position: fixed;
      right: 1rem;
      bottom: 1rem;
      z-index: 30;
      max-width: min(24rem, calc(100% - 2rem));
      padding: 1rem 1.1rem;
      color: #171008;
      background: var(--accent-strong);
      border-radius: var(--radius-sm);
      box-shadow: 0 18px 44px #00000085;
      font-weight: 900;
      transform: translateY(150%);
      transition: transform 220ms ease;
    }

    .toast.is-visible {
      transform: translateY(0);
    }

    .visually-hidden {
      position: absolute;
      width: 1px;
      height: 1px;
      padding: 0;
      margin: -1px;
      overflow: hidden;
      clip: rect(0, 0, 0, 0);
      white-space: nowrap;
      border: 0;
    }

    @media (max-width: 860px) {
      .nav-toggle {
        display: inline-flex;
      }

      .primary-nav {
        position: fixed;
        inset: 76px 1rem auto;
        display: none;
        padding: 1rem;
        background: #08090d;
        border: 1px solid var(--border);
        border-radius: var(--radius-md);
        box-shadow: 0 24px 60px #000000b3;
      }

      .primary-nav.is-open {
        display: block;
      }

      .primary-nav ul {
        display: grid;
        gap: 0.35rem;
      }

      .primary-nav a {
        width: 100%;
      }

      .hero,
      .deal-panel,
      .newsletter {
        grid-template-columns: 1fr;
      }

      .hero-card {
        min-height: 460px;
      }

      .product-grid,
      .editorial-grid {
        grid-template-columns: repeat(2, minmax(0, 1fr));
      }
    }

    @media (max-width: 620px) {
      .header-inner,
      .section,
      .footer-inner {
        width: min(100% - 1rem, var(--max-width));
      }

      .brand span:last-child {
        max-width: 8.5rem;
        overflow: hidden;
        text-overflow: ellipsis;
      }

      .header-actions {
        gap: 0.45rem;
      }

      .cart-pill {
        padding-inline: 0.7rem;
      }

      .hero-card {
        min-height: 400px;
      }

      .showcase-bag {
        min-height: 17rem;
      }

      .product-grid,
      .editorial-grid,
      .countdown {
        grid-template-columns: 1fr;
      }

      .form-row {
        flex-direction: column;
      }

      .form-row .button {
        width: 100%;
      }
    }

    @media (prefers-reduced-motion: reduce) {
      *,
      *::before,
      *::after {
        scroll-behavior: auto !important;
        transition-duration: 0.01ms !important;
        animation-duration: 0.01ms !important;
        animation-iteration-count: 1 !important;
      }
    }

    @media (forced-colors: active) {
      :root {
        --bg: Canvas;
        --surface: Canvas;
        --surface-strong: Canvas;
        --surface-soft: Canvas;
        --text: CanvasText;
        --muted: CanvasText;
        --accent: LinkText;
        --accent-strong: ButtonText;
        --border: ButtonBorder;
      }

      .button,
      .brand-mark,
      .spark,
      .cart-count,
      .filter-button[aria-pressed="true"],
      .deal-badge,
      .toast {
        border: 2px solid ButtonBorder;
      }
    }
  </style>
</head>
<body>
  <a class="skip-link" href="#main">Skip to main content</a>

  <header class="site-header">
    <div class="header-inner">
      <a class="brand" href="#" aria-label="Nova and Co. home">
        <span class="brand-mark" aria-hidden="true">N</span>
        <span>Nova &amp; Co.</span>
      </a>

      <button class="nav-toggle" type="button" aria-expanded="false" aria-controls="primary-navigation">
        Menu
      </button>

      <nav class="primary-nav" id="primary-navigation" aria-label="Primary navigation">
        <ul>
          <li><a href="#featured">Featured</a></li>
          <li><a href="#deals">Deals</a></li>
          <li><a href="#editorial">Editorial</a></li>
          <li><a href="#newsletter">Insider List</a></li>
        </ul>
      </nav>

      <div class="header-actions">
        <a class="button secondary" href="#featured">Shop now</a>
        <div class="cart-pill" aria-live="polite">
          Bag <span class="cart-count" id="cart-count">0</span>
        </div>
      </div>
    </div>
  </header>

  <main id="main">
    <section class="section hero" aria-labelledby="hero-title">
      <div>
        <p class="eyebrow">New season edit</p>
        <h1 id="hero-title">Retail made cinematic.</h1>
        <p class="hero-copy">
          Discover sculptural essentials, limited-run home goods, and after-dark accessories curated for a sharper everyday ritual.
        </p>
        <div class="hero-actions">
          <a class="button" href="#featured">Explore featured products</a>
          <a class="button secondary" href="#editorial">Read the style journal</a>
        </div>
      </div>

      <div class="hero-card" aria-label="Featured Nova signature tote presentation">
        <div class="product-stage">
          <div class="showcase-bag" aria-hidden="true"></div>
          <div class="floating-note">
            <span class="spark" aria-hidden="true">25</span>
            <div>
              <strong>Members preview</strong>
              <p>Early access to the Solstice capsule opens tonight.</p>
            </div>
          </div>
        </div>
      </div>
    </section>

    <section class="section" id="featured" aria-labelledby="featured-title">
      <div class="section-heading">
        <div>
          <p class="eyebrow">Featured products</p>
          <h2 id="featured-title">Objects with presence</h2>
        </div>
        <p>Shop tactile materials, precise silhouettes, and quiet statement pieces selected by the Nova buying team.</p>
      </div>

      <div class="category-controls" aria-label="Filter featured products">
        <button class="filter-button" type="button" data-filter="all" aria-pressed="true">All</button>
        <button class="filter-button" type="button" data-filter="wear">Wear</button>
        <button class="filter-button" type="button" data-filter="home">Home</button>
        <button class="filter-button" type="button" data-filter="carry">Carry</button>
      </div>

      <div class="product-grid" id="product-grid">
        <article class="product-card" data-category="carry">
          <div class="product-media">
            <div class="product-shape" style="--product-gradient: linear-gradient(145deg, #f4d17a, #654117); --shape: 34% 34% 24% 24%;" aria-hidden="true">N</div>
          </div>
          <div class="product-body">
            <div>
              <h3>Obsidian City Tote</h3>
              <p>Full-grain leather carryall with a midnight lining and brass hardware.</p>
            </div>
            <div class="product-meta">
              <span class="price">$248</span>
              <span class="rating" aria-label="Rated 4.9 out of 5 stars">4.9 stars</span>
            </div>
            <button class="button add-to-bag" type="button" data-product="Obsidian City Tote">Add Obsidian City Tote to bag</button>
          </div>
        </article>

        <article class="product-card" data-category="wear">
          <div class="product-media">
            <div class="product-shape" style="--product-gradient: linear-gradient(145deg, #d9dde8, #4e5367); --shape: 999px;" aria-hidden="true">O</div>
          </div>
          <div class="product-body">
            <div>
              <h3>Mercury Knit Set</h3>
              <p>Structured merino separates designed for travel days and gallery nights.</p>
            </div>
            <div class="product-meta">
              <span class="price">$186</span>
              <span class="rating" aria-label="Rated 4.8 out of 5 stars">4.8 stars</span>
            </div>
            <button class="button add-to-bag" type="button" data-product="Mercury Knit Set">Add Mercury Knit Set to bag</button>
          </div>
        </article>

        <article class="product-card" data-category="home">
          <div class="product-media">
            <div class="product-shape" style="--product-gradient: linear-gradient(145deg, #f0c05a, #8a2f20); --shape: 30px;" aria-hidden="true">+</div>
          </div>
          <div class="product-body">
            <div>
              <h3>Amber Glass Lamp</h3>
              <p>Hand-blown table light with a warm dimmer and smoky bronze base.</p>
            </div>
            <div class="product-meta">
              <span class="price">$164</span>
              <span class="rating" aria-label="Rated 4.7 out of 5 stars">4.7 stars</span>
            </div>
            <button class="button add-to-bag" type="button" data-product="Amber Glass Lamp">Add Amber Glass Lamp to bag</button>
          </div>
        </article>
      </div>
    </section>

    <section class="section" id="deals" aria-labelledby="deals-title">
      <div class="deal-panel">
        <div class="deal-copy">
          <span class="deal-badge">Private sale</span>
          <h2 id="deals-title">Up to 35% off the after-hours edit</h2>
          <p>
            For a limited time, save on tailored layers, elevated fragrance, and home accents that make winter evenings feel intentional.
          </p>
          <div class="deal-actions">
            <a class="button" href="#featured">Shop the sale</a>
            <a class="button secondary" href="#newsletter">Unlock member perks</a>
          </div>
        </div>
        <div>
          <p class="visually-hidden" id="countdown-label">Sale countdown timer showing hours, minutes, and seconds remaining.</p>
          <div class="countdown" aria-labelledby="countdown-label" aria-live="polite">
            <div class="time-box"><span><strong id="hours">12</strong>Hours</span></div>
            <div class="time-box"><span><strong id="minutes">00</strong>Minutes</span></div>
            <div class="time-box"><span><strong id="seconds">00</strong>Seconds</span></div>
          </div>
        </div>
      </div>
    </section>

    <section class="section" id="editorial" aria-labelledby="editorial-title">
      <div class="section-heading">
        <div>
          <p class="eyebrow">Editorial content</p>
          <h2 id="editorial-title">The Nova journal</h2>
        </div>
        <p>Field notes from stylists, makers, and buyers on how to live with fewer, better things.</p>
      </div>

      <div class="editorial-grid">
        <article class="article-card">
          <div class="article-media" style="--article-a: #6b3f16; --article-b: #e4b75c;" aria-hidden="true"></div>
          <div class="article-body">
            <span class="article-tag">Guide</span>
            <h3>Five textures that make a room feel collected</h3>
            <p>Layer metal, matte ceramic, heavy linen, and reflective glass without overwhelming a dark palette.</p>
            <a href="#newsletter">Read the texture guide</a>
          </div>
        </article>

        <article class="article-card">
          <div class="article-media" style="--article-a: #1f355e; --article-b: #d8a74e;" aria-hidden="true"></div>
          <div class="article-body">
            <span class="article-tag">Interview</span>
            <h3>Inside the workshop behind our signature tote</h3>
            <p>Meet the small-batch makers balancing durable construction with a refined architectural profile.</p>
            <a href="#newsletter">Meet the makers</a>
          </div>
        </article>

        <article class="article-card">
          <div class="article-media" style="--article-a: #4b2038; --article-b: #f1c86a;" aria-hidden="true"></div>
          <div class="article-body">
            <span class="article-tag">Edit</span>
            <h3>How to pack one week in one beautiful bag</h3>
            <p>A retail editor's compact capsule for quick departures, late dinners, and polished arrivals.</p>
            <a href="#newsletter">Open the packing edit</a>
          </div>
        </article>
      </div>
    </section>

    <section class="section" id="newsletter" aria-labelledby="newsletter-title">
      <div class="newsletter">
        <div>
          <p class="eyebrow">Insider list</p>
          <h2 id="newsletter-title">Get the first look.</h2>
          <p>Join for early access to drops, private sale codes, and editorial dispatches from the Nova buying desk.</p>
        </div>
        <form class="newsletter-form" id="newsletter-form" novalidate>
          <label for="email">Email address <span aria-hidden="true">*</span></label>
          <div class="form-row">
            <input id="email" name="email" type="email" autocomplete="email" required aria-describedby="email-help email-error email-success">
            <button class="button" type="submit">Join the insider list</button>
          </div>
          <p class="form-help" id="email-help">Required. We will send retail updates only; unsubscribe anytime.</p>
          <p class="form-error" id="email-error"></p>
          <p class="form-success" id="email-success" aria-live="polite"></p>
        </form>
      </div>
    </section>
  </main>

  <footer class="site-footer">
    <div class="footer-inner">
      <p>&copy; 2026 Nova &amp; Co. Curated retail for modern rituals.</p>
      <nav aria-label="Footer navigation">
        <ul>
          <li><a href="#featured">Products</a></li>
          <li><a href="#deals">Deals</a></li>
          <li><a href="#editorial">Journal</a></li>
          <li><a href="#newsletter">Newsletter</a></li>
        </ul>
      </nav>
    </div>
  </footer>

  <div class="toast" id="toast" aria-live="polite" aria-atomic="true"></div>

  <script>
    const navToggle = document.querySelector(".nav-toggle");
    const primaryNav = document.querySelector(".primary-nav");
    const filterButtons = document.querySelectorAll(".filter-button");
    const products = document.querySelectorAll(".product-card");
    const cartCount = document.querySelector("#cart-count");
    const toast = document.querySelector("#toast");
    const addButtons = document.querySelectorAll(".add-to-bag");
    const newsletterForm = document.querySelector("#newsletter-form");
    const emailInput = document.querySelector("#email");
    const emailError = document.querySelector("#email-error");
    const emailSuccess = document.querySelector("#email-success");
    const countdownEnd = Date.now() + 12 * 60 * 60 * 1000;
    let cartTotal = 0;
    let toastTimer;

